Json audit(const Geometry&g){auto plan=build_render_batches(g);std::vector<const Mesh*>meshes;std::vector<bool>need(g.meshes.size());for(auto i:plan.unbatched)need[i]=true;for(auto&b:plan.batches){meshes.push_back(&b.mesh);if(!b.props.empty())for(auto i:b.members)need[i]=true;}for(size_t i=0;i<need.size();i++)if(need[i]&&!g.meshes[i].indices.empty())meshes.push_back(&g.meshes[i]);std::set<std::array<uint64_t,3>>seen;size_t before=0,after=0,old_buffers=0,new_buffers=0,compact=0,vb=0;for(auto m:meshes){std::array<uint64_t,3>key{1469598103934665603ull,1099511628211ull,uint64_t(m->vertices.size())<<32|uint64_t(m->indices.size())};auto hash=[&](const void*data,size_t n){auto p=static_cast<const uint8_t*>(data);for(size_t i=0;i<n;i++){key[0]=(key[0]^p[i])*1099511628211ull;key[1]=(key[1]+p[i]+0x9e3779b9ull)*0x100000001b3ull;}};hash(m->vertices.data(),m->vertices.size()*sizeof(Vertex));hash(m->indices.data(),m->indices.size()*4);if(!seen.insert(key).second)continue;vb+=m->vertices.size()*sizeof(Vertex);auto levels=m->billboard?MeshLods{{m->indices,m->indices,m->indices},{}}:build_mesh_lods(m->vertices,m->indices);for(int l=0;l<3;l++){before+=levels.indices[l].size()*4;++old_buffers;if(duplicate_index_level(levels.indices,l)<l)continue;bool small=compact_indices(levels.indices[l]);after+=levels.indices[l].size()*(small?2:4);++new_buffers;compact+=small;}}return{{"uploaded_mesh_references",meshes.size()},{"unique_geometry_buffers",seen.size()},{"vertex_bytes_unchanged",vb},{"old_index_bytes",before},{"compact_shared_index_bytes",after},{"index_bytes_saved",before-after},{"old_index_buffers",old_buffers},{"compact_shared_index_buffers",new_buffers},{"index16_buffers",compact},{"source_triangles",g.triangles},{"planned_triangles",plan.report["planned_triangles"]}};}
int main(int argc,char**argv){try{if(argc<4)throw std::runtime_error("Usage: OpenFOGpuStorageAudit DATA PACKAGE OUT_JSON");Resources r(argv[1]);r.mount(fs::path(argv[2])/"capture_assets","capture_assets");auto menu=load_geometry(r,"tracks/menu/menu1/geometry/track_geom.w32");auto forest=load_geometry(r,"tracks/forest/forest1/geometry/track_geom.w32");append_captured_scene(forest,r);Json out={{"scope","Host calculation of actual renderer index policy; same full geometry and LOD levels; excludes driver allocation/alignment, textures and grass; not measured VRAM or FPS"},{"menu",audit(menu)},{"forest",audit(forest)}};std::ofstream(argv[3])<<out.dump(2);std::cout<<out.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
